CREATE TABLE IF NOT EXISTS client_portal_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_portal_client(client_id),CONSTRAINT fk_portal_user_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_portal_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_portal_session_user FOREIGN KEY(user_id) REFERENCES client_portal_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_portal_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NOT NULL,project_id BIGINT UNSIGNED NULL,name VARCHAR(255) NOT NULL,file_path VARCHAR(500) NOT NULL,category VARCHAR(100) NULL,is_visible TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_portal_doc_client(client_id),CONSTRAINT fk_portal_doc_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE,CONSTRAINT fk_portal_doc_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_portal_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,staff_id BIGINT UNSIGNED NULL,subject VARCHAR(255) NULL,message TEXT NOT NULL,direction ENUM('client','staff') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_portal_msg_client(client_id),CONSTRAINT fk_portal_msg_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE,CONSTRAINT fk_portal_msg_user FOREIGN KEY(user_id) REFERENCES client_portal_users(id) ON DELETE SET NULL,CONSTRAINT fk_portal_msg_staff FOREIGN KEY(staff_id) REFERENCES staff_members(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_portal_activity (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,activity_type VARCHAR(100) NOT NULL,reference_type VARCHAR(100) NULL,reference_id BIGINT UNSIGNED NULL,description VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_portal_activity_client(client_id),CONSTRAINT fk_portal_activity_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE,CONSTRAINT fk_portal_activity_user FOREIGN KEY(user_id) REFERENCES client_portal_users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_portal_settings (client_id BIGINT UNSIGNED PRIMARY KEY,notification_email TINYINT(1) NOT NULL DEFAULT 1,notification_ticket TINYINT(1) NOT NULL DEFAULT 1,notification_invoice TINYINT(1) NOT NULL DEFAULT 1,timezone VARCHAR(80) NOT NULL DEFAULT 'Africa/Lagos',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_portal_setting_client FOREIGN KEY(client_id) REFERENCES clients(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;